/* @lc app=leetcode id=3919 lang=kotlin */ class Solution { fun minCost(nums: IntArray, queries: Array<IntArray>): LongArray = nums.size.let { n -> IntArray(n) { x -> if (x > 0 && (x == n - 1 || nums[x].toLong() - nums[x - 1] <= nums[x + 1].toLong() - nums[x])) x - 1 else x + 1 }.let { cl -> nums.indices.map { i -> if (i < n - 1) (if (cl[i] == i + 1) 1L else nums[i + 1].toLong() - nums[i]) else 0L }.runningFold(0L) { a, b -> a + b }.let { pf -> nums.indices.map { i -> if (i > 0) (if (cl[i] == i - 1) 1L else nums[i].toLong() - nums[i - 1]) else 0L }.runningFold(0L) { a, b -> a + b }.let { pb -> queries.map { (l, r) -> if (l < r) pf[r] - pf[l] else if (l > r) pb[l + 1] - pb[r + 1] else 0L }.toLongArray() } } } } }